"use client";
import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Check, ChevronRight, Copy, RotateCcw, Square, X } from "lucide-react";
import { reducedMotionNow } from "../hooks/reduced-motion";
import type { AssistantPhase, Source, ToolStep } from "../hooks/assistant";

export interface AIResponseProps {
  /** Where the response is, from `useAssistant`. */
  phase: AssistantPhase;
  /** Everything that has arrived so far. */
  text: string;
  /** Tool calls in the order they were made. */
  steps: ToolStep[];
  /** Sources the tools returned. Only the ones the text cites are listed. */
  sources: Source[];
  /** Seconds since anything arrived, once that is past the slow threshold; 0 otherwise. */
  stalledS?: number;
  /** Shown when the response fails. */
  error?: string;
  onStop?: () => void;
  onRetry?: () => void;
  /** Who is answering. Default: "Assistant" */
  name?: string;
  className?: string;
}

const STEP_LABEL: Record<string, (args: Record<string, unknown>) => string> = {
  search_components: (a) => `Searched components for “${String(a.query ?? "")}”`,
  get_component: (a) => `Opened ${String(a.slug ?? "a component")}`,
};
const stepLabel = (s: ToolStep) => STEP_LABEL[s.name]?.(s.args) ?? s.name.replace(/_/g, " ");

const STATUS: Partial<Record<AssistantPhase, string>> = {
  thinking: "Thinking",
  tool: "Using a tool",
  stopped: "Stopped",
  done: "Done",
};

/** Paragraphs, `code`, **bold** and [n] citations, the only formatting an answer here needs. */
const renderText = (text: string, sources: Source[], caret: ReactNode) =>
  text
    .split(/\n{2,}/)
    .filter((p) => p.trim())
    .map((para, i, all) => (
      <p key={i} className="mt-3 first:mt-0">
        {para.split(/(\[\d+\]|`[^`]+`|\*\*[^*]+\*\*)/g).map((part, j): ReactNode => {
          const cite = part.match(/^\[(\d+)\]$/);
          if (cite) {
            const source = sources.find((s) => s.n === Number(cite[1]));
            // A number with no source behind it is shown as plain text, never as a link.
            if (!source) return part;
            return (
              <sup key={j} className="mx-0.5">
                <a
                  href={source.href}
                  aria-label={`Source ${source.n}: ${source.title}`}
                  className="rounded px-1 font-mono text-[10px] text-white/70 ring-1 ring-white/20 hover:text-white hover:ring-white/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
                >
                  {source.n}
                </a>
              </sup>
            );
          }
          if (part.startsWith("`") && part.endsWith("`") && part.length > 2)
            return (
              <code key={j} className="rounded bg-white/[0.07] px-1 py-0.5 font-mono text-[12px] text-white/85">
                {part.slice(1, -1)}
              </code>
            );
          if (part.startsWith("**") && part.endsWith("**") && part.length > 4) return <strong key={j} className="font-medium text-white">{part.slice(2, -2)}</strong>;
          return part;
        })}
        {i === all.length - 1 && caret}
      </p>
    ));

const StepRow = ({ step }: { step: ToolStep }) => {
  const [open, setOpen] = useState(false);
  return (
    <li className="text-[12px]">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-white/60 hover:bg-white/[0.04] hover:text-white/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/50"
      >
        <span aria-hidden="true" className="flex h-4 w-4 shrink-0 items-center justify-center">
          {step.status === "running" ? (
            <span className="h-1.5 w-1.5 rounded-full bg-white/70 motion-safe:animate-pulse" />
          ) : step.status === "done" ? (
            <Check size={13} className="text-[#86efac]" />
          ) : (
            <X size={13} className="text-[#fca5a5]" />
          )}
        </span>
        <span className="min-w-0 flex-1 truncate">
          {stepLabel(step)}
          {step.summary && <span className={step.status === "failed" ? "text-[#fca5a5]/90" : "text-white/40"}> · {step.summary}</span>}
        </span>
        <span className="sr-only">{step.status === "running" ? "running" : step.status === "done" ? "done" : "failed"}</span>
        <ChevronRight aria-hidden="true" size={12} className={`shrink-0 text-white/30 ${open ? "rotate-90" : ""}`} />
      </button>
      {open && (
        <pre className="mx-2 mb-1 mt-0.5 overflow-x-auto rounded-lg bg-white/[0.03] px-3 py-2 font-mono text-[11px] leading-relaxed text-white/55">
          {JSON.stringify({ tool: step.name, arguments: step.args }, null, 2)}
        </pre>
      )}
    </li>
  );
};

/**
 * An AI response that is honest about where it is. Each state reads
 * differently, and none of them pretends:
 *
 * - Nothing is drawn for a response that starts quickly; past the quiet
 *   window it says it is thinking.
 * - Each tool call appears as a step as it runs, with its arguments one
 *   click away, and a failed step says what failed.
 * - Text arrives in bursts and is revealed at an even, spring-smoothed pace,
 *   so it reads instead of jumping.
 * - Citations link to their sources, and a number with no source behind it
 *   is never turned into a link.
 * - When nothing has arrived for a while it says so, with the time and a Stop.
 *   Stopping keeps what arrived. A failure keeps it too, and offers Retry.
 *
 * Screen readers hear the finished answer once, not every token.
 *
 * @example
 * const a = useAssistant();
 * <AIResponse {...a} onStop={a.stop} onRetry={() => a.start(source)} />
 */
export const AIResponse = ({ phase, text, steps, sources, stalledS = 0, error, onStop, onRetry, name = "Assistant", className = "" }: AIResponseProps) => {
  const [shown, setShown] = useState(0);
  const [copied, setCopied] = useState(false);
  const target = useRef(text.length);
  // Stopped or failed: show what arrived at once, so the halt is visible rather than the text typing on.
  const halted = useRef(false);
  useLayoutEffect(() => {
    target.current = text.length;
    halted.current = phase === "stopped" || phase === "error";
  });

  // Reveal at an even pace: the backlog drains a fixed share per frame, so bursts are smoothed and a long backlog still catches up fast.
  useEffect(() => {
    let raf = 0;
    let current = 0;
    let last = -1;
    const tick = () => {
      const goal = target.current;
      if (goal < current || halted.current || reducedMotionNow()) current = goal;
      else if (goal > current) current = Math.min(goal, current + Math.max(0.6, (goal - current) * 0.14));
      const n = Math.floor(current);
      if (n !== last) {
        last = n;
        setShown(n);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  const busy = phase === "waiting" || phase === "thinking" || phase === "tool" || phase === "streaming";
  const revealing = shown < text.length;
  const visible = text.slice(0, shown);
  const cited = sources.filter((s) => new RegExp(`\\[${s.n}\\]`).test(text));
  const settled = phase === "done" || phase === "stopped" || phase === "error";
  const status = stalledS > 0 && busy ? `Still working · ${stalledS}s` : phase === "error" ? (error ?? "Something went wrong") : STATUS[phase];

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      // Clipboard can be blocked; nothing else to do.
    }
  };

  // What a screen reader hears: the whole answer once it is finished, or why it stopped.
  const announcement =
    phase === "done" && !revealing ? `${name} answered: ${text}` : phase === "stopped" ? `${name} stopped.` : phase === "error" ? `${name} failed: ${error ?? ""}` : "";

  if (phase === "idle") return null;

  return (
    <article aria-label={`${name} response`} aria-busy={busy || revealing} className={`min-w-0 rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5 ${className}`}>
      <header className="flex items-center gap-2.5">
        <span aria-hidden="true" className={`h-2 w-2 rounded-full ${busy ? "bg-white/80 motion-safe:animate-pulse" : phase === "error" ? "bg-[#fca5a5]" : "bg-white/40"}`} />
        <span className="text-[13px] text-white/80">{name}</span>
        {status && phase !== "waiting" && (
          <span className={`font-mono text-[11px] ${phase === "error" ? "text-[#fca5a5]" : "text-white/40"}`}>{status}</span>
        )}
      </header>

      {steps.length > 0 && (
        <ol aria-label="Steps" className="mt-3 grid grid-cols-[minmax(0,1fr)] gap-0.5 border-l border-white/[0.08] pl-2">
          {steps.map((s) => (
            <StepRow key={s.id} step={s} />
          ))}
        </ol>
      )}

      {visible && (
        <div className="mt-4 text-[14px] leading-relaxed text-white/80">
          {renderText(
            visible,
            sources,
            (busy || revealing) && <span aria-hidden="true" className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[3px] bg-white/60" />
          )}
        </div>
      )}

      {settled && !revealing && cited.length > 0 && (
        <div className="mt-4 border-t border-white/[0.06] pt-3">
          <p className="font-mono text-[10px] uppercase tracking-[0.16em] text-white/35">Sources</p>
          <ol className="mt-2 grid gap-1">
            {cited.map((s) => (
              <li key={s.n} className="flex items-center gap-2 text-[12px]">
                <span className="font-mono text-white/40">{s.n}</span>
                <a href={s.href} className="text-white/70 underline decoration-white/20 underline-offset-2 hover:text-white hover:decoration-white/50">
                  {s.title}
                </a>
              </li>
            ))}
          </ol>
        </div>
      )}

      <div className="mt-4 flex flex-wrap items-center gap-2">
        {busy && onStop && (
          <button
            type="button"
            onClick={onStop}
            className="inline-flex items-center gap-1.5 rounded-lg border border-white/[0.12] bg-white/[0.04] px-3 py-1.5 text-[12px] text-white/80 hover:bg-white/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            <Square size={11} aria-hidden="true" />
            Stop
          </button>
        )}
        {settled && onRetry && (
          <button
            type="button"
            onClick={onRetry}
            className="inline-flex items-center gap-1.5 rounded-lg border border-white/[0.12] bg-white/[0.04] px-3 py-1.5 text-[12px] text-white/80 hover:bg-white/[0.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            <RotateCcw size={11} aria-hidden="true" />
            {phase === "done" ? "Regenerate" : "Retry"}
          </button>
        )}
        {settled && text && (
          <button
            type="button"
            onClick={copy}
            className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[12px] text-white/55 hover:bg-white/[0.05] hover:text-white/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
          >
            {copied ? <Check size={11} aria-hidden="true" /> : <Copy size={11} aria-hidden="true" />}
            {copied ? "Copied" : "Copy"}
          </button>
        )}
      </div>

      <div className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {announcement}
      </div>
    </article>
  );
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";
import { QUIET_MS, SLOW_MS } from "./latency";

/**
 * The states of an AI response, and one source interface for where it comes from.
 *
 * The interface does not know whether a response is live or a replay: both
 * are a `StreamSource`, an async stream of events. The demo replays real
 * recordings with their real timing, so a visitor costs nothing, and a live
 * model would plug into the same hook unchanged.
 *
 * The timing rules are the latency states': nothing new is drawn for a
 * response that starts inside QUIET_MS, and once nothing has arrived for
 * SLOW_MS the response says it is still working and offers a way out.
 */

export type Source = { n: number; title: string; href: string };

export type StreamEvent =
  | { t: number; type: "text"; text: string }
  | { t: number; type: "tool_call"; id: string; name: string; args: Record<string, unknown> }
  | { t: number; type: "tool_result"; id: string; ok: boolean; summary: string; sources?: Source[] }
  | { t: number; type: "error"; message: string }
  | { t: number; type: "done" };

export type Recording = {
  id: string;
  title: string;
  prompt: string;
  /** How it was recorded, and anything injected. Shown beside the replay. */
  note: string;
  model: string;
  recordedAt: string;
  sources: Source[];
  events: StreamEvent[];
};

/** Anything that yields response events. Must stop when the signal aborts. */
export type StreamSource = (signal: AbortSignal) => AsyncIterable<StreamEvent>;

/**
 * Play a recording back at its recorded pace (scaled by `speed`), honouring
 * the abort signal between events. `cutAt` ends the stream early with an
 * error, to show a connection dropping mid-answer.
 */
export const replay =
  (recording: Recording, { speed = 1, cutAt }: { speed?: number; cutAt?: number } = {}): StreamSource =>
  (signal) => ({
    async *[Symbol.asyncIterator]() {
      const start = performance.now();
      for (const event of recording.events) {
        if (cutAt !== undefined && event.t >= cutAt) {
          await wait(start + cutAt / speed - performance.now(), signal);
          yield { t: cutAt, type: "error", message: "The connection dropped." } satisfies StreamEvent;
          return;
        }
        await wait(start + event.t / speed - performance.now(), signal);
        if (signal.aborted) return;
        yield event;
      }
    },
  });

const wait = (ms: number, signal: AbortSignal) =>
  new Promise<void>((resolve) => {
    if (ms <= 0 || signal.aborted) return resolve();
    const timer = window.setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      window.clearTimeout(timer);
      resolve();
    }, { once: true });
  });

export type AssistantPhase =
  /** Nothing asked yet. */
  | "idle"
  /** Asked, inside the quiet window: nothing new is drawn. */
  | "waiting"
  /** Past the quiet window with nothing back yet. */
  | "thinking"
  /** A tool is running. */
  | "tool"
  /** Text is arriving. */
  | "streaming"
  | "done"
  /** Stopped by the user. What arrived is kept. */
  | "stopped"
  | "error";

export type ToolStep = {
  id: string;
  name: string;
  args: Record<string, unknown>;
  status: "running" | "done" | "failed";
  summary?: string;
};

type State = {
  phase: AssistantPhase;
  text: string;
  steps: ToolStep[];
  sources: Source[];
  error: string;
};

type Action = { type: "start" } | { type: "quiet-over" } | { type: "event"; event: StreamEvent } | { type: "stop" } | { type: "reset" };

const INITIAL: State = { phase: "idle", text: "", steps: [], sources: [], error: "" };

const busy = (phase: AssistantPhase) => phase === "waiting" || phase === "thinking" || phase === "tool" || phase === "streaming";

const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "start":
      return { ...INITIAL, phase: "waiting" };
    case "quiet-over":
      return state.phase === "waiting" ? { ...state, phase: "thinking" } : state;
    case "stop":
      return busy(state.phase) ? { ...state, phase: "stopped", steps: state.steps.map((s) => (s.status === "running" ? { ...s, status: "failed", summary: "Stopped" } : s)) } : state;
    case "reset":
      return INITIAL;
    case "event": {
      if (!busy(state.phase)) return state; // a late event cannot move a settled response
      const e = action.event;
      switch (e.type) {
        case "text":
          return { ...state, phase: "streaming", text: state.text + e.text };
        case "tool_call":
          return { ...state, phase: "tool", steps: [...state.steps, { id: e.id, name: e.name, args: e.args, status: "running" }] };
        case "tool_result": {
          const sources = [...state.sources];
          for (const s of e.sources ?? []) if (!sources.some((x) => x.n === s.n)) sources.push(s);
          return {
            ...state,
            phase: "thinking",
            sources,
            steps: state.steps.map((s) => (s.id === e.id ? { ...s, status: e.ok ? "done" : "failed", summary: e.summary } : s)),
          };
        }
        case "error":
          return { ...state, phase: "error", error: e.message };
        case "done":
          return { ...state, phase: "done" };
      }
    }
  }
};

export interface AssistantOptions {
  quietMs?: number;
  slowMs?: number;
}

/**
 * Run a response through its states.
 *
 * @example
 * const a = useAssistant();
 * a.start(replay(recording, { speed: 3 }));
 */
export const useAssistant = ({ quietMs = QUIET_MS, slowMs = SLOW_MS }: AssistantOptions = {}) => {
  const [state, dispatch] = useReducer(reducer, INITIAL);
  const [stalledS, setStalledS] = useState(0);
  const controller = useRef<AbortController | null>(null);
  const run = useRef(0);
  const lastEventAt = useRef(0);
  const phaseRef = useRef(state.phase);
  useEffect(() => {
    phaseRef.current = state.phase;
  }, [state.phase]);

  const stop = useCallback(() => {
    run.current++;
    controller.current?.abort();
    dispatch({ type: "stop" });
  }, []);

  const reset = useCallback(() => {
    run.current++;
    controller.current?.abort();
    dispatch({ type: "reset" });
  }, []);

  const start = useCallback(
    (source: StreamSource) => {
      controller.current?.abort();
      const id = ++run.current;
      const ctl = new AbortController();
      controller.current = ctl;
      dispatch({ type: "start" });
      lastEventAt.current = performance.now();
      const quiet = window.setTimeout(() => id === run.current && dispatch({ type: "quiet-over" }), quietMs);
      (async () => {
        try {
          for await (const event of source(ctl.signal)) {
            if (id !== run.current) return;
            lastEventAt.current = performance.now();
            dispatch({ type: "event", event });
          }
        } catch (err) {
          if (id === run.current) dispatch({ type: "event", event: { t: 0, type: "error", message: err instanceof Error ? err.message : "Something went wrong." } });
        } finally {
          window.clearTimeout(quiet);
        }
      })();
    },
    [quietMs]
  );

  // How long since anything arrived, once that passes slowMs. Ticks only while busy.
  useEffect(() => {
    if (!busy(state.phase)) return;
    const timer = window.setInterval(() => {
      const quietFor = performance.now() - lastEventAt.current;
      setStalledS(quietFor >= slowMs ? Math.floor(quietFor / 1000) : 0);
    }, 250);
    return () => {
      window.clearInterval(timer);
      setStalledS(0);
    };
  }, [state.phase, slowMs]);

  useEffect(() => () => controller.current?.abort(), []);

  return { ...state, busy: busy(state.phase), stalledS, start, stop, reset };
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";

/**
 * Latency states: one honest lifecycle for anything that waits on a request.
 *
 * It is a state, not a component. The async button and the loading region
 * both run on it, and anything else that waits (a select that fetches its
 * options, a search box, a save bar) can take the same hook and get the same
 * timing rules for free:
 *
 * - pending: a request is out but under the skeleton threshold, so nothing
 *   new is drawn. A fast response never flashes a placeholder.
 * - skeleton: it has passed that threshold (only if you ask for one).
 * - slow: it has taken long enough that the interface should say so.
 * - success / error / cancelled: settled. START runs it again, RESET clears it.
 */
/** Under this, show nothing new: a fast response never flashes a placeholder. Shared by every waiting surface. */
export const QUIET_MS = 400;
/** Past this with no progress, say it is slow and offer a way out. */
export const SLOW_MS = 2000;

export type LatencyPhase = "idle" | "pending" | "skeleton" | "slow" | "success" | "error" | "cancelled";

export type LatencyEvent = "START" | "SHOW_SKELETON" | "SLOW" | "RESOLVE" | "REJECT" | "CANCEL" | "RESET";

/** Every legal transition. Anything not listed is ignored, so a late result cannot move a settled state. */
export const LATENCY_TRANSITIONS: Record<LatencyPhase, Partial<Record<LatencyEvent, LatencyPhase>>> = {
  idle: { START: "pending" },
  pending: { SHOW_SKELETON: "skeleton", SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  skeleton: { SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  slow: { RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  success: { START: "pending", RESET: "idle" },
  error: { START: "pending", RESET: "idle" },
  cancelled: { START: "pending", RESET: "idle" },
};

export const latencyReducer = (state: LatencyPhase, event: LatencyEvent): LatencyPhase =>
  LATENCY_TRANSITIONS[state][event] ?? state;

/**
 * The part of the machine one component uses: only these phases, reached
 * only by these events. A component that never shows a skeleton or never
 * cancels draws its own machine from this, and it is still the shared one.
 */
export const sliceTransitions = <P extends LatencyPhase, E extends LatencyEvent>(phases: readonly P[], events: readonly E[]) =>
  Object.fromEntries(
    phases.map((from) => [
      from,
      Object.fromEntries(
        Object.entries(LATENCY_TRANSITIONS[from]).filter(
          ([event, to]) => events.includes(event as E) && phases.includes(to as P)
        )
      ),
    ])
  ) as Record<P, Partial<Record<E, P>>>;

export const isBusy = (phase: LatencyPhase) => phase === "pending" || phase === "skeleton" || phase === "slow";

export interface LatencyLogEntry {
  /** Milliseconds since the request started (0 for START). */
  atMs: number;
  event: LatencyEvent;
  from: LatencyPhase;
  to: LatencyPhase;
}

export interface LatencyOptions<T> {
  /** The request. Honour `signal` if you can; late results are ignored either way. */
  run: (signal: AbortSignal) => Promise<T>;
  /** Show a skeleton after this long. Leave undefined to never show one. */
  skeletonAfterMs?: number;
  /** Say it is slow after this long. */
  slowAfterMs?: number;
  /** Return to idle this long after success. Leave undefined to stay on success. */
  successHoldMs?: number;
  /** Every real state change, with time since the request started. */
  onEvent?: (entry: LatencyLogEntry) => void;
}

/**
 * Run a request through the latency states.
 *
 * @example
 * const { phase, start } = useLatency({ run: (signal) => fetch("/api", { signal }), slowAfterMs: 1500 });
 */
export const useLatency = <T>({ run, skeletonAfterMs, slowAfterMs = SLOW_MS, successHoldMs, onEvent }: LatencyOptions<T>) => {
  const [phase, dispatch] = useReducer(latencyReducer, "idle");
  const phaseRef = useRef<LatencyPhase>("idle");
  const [data, setData] = useState<{ value: T } | null>(null);
  const [error, setError] = useState("");
  const [elapsedS, setElapsedS] = useState(0);

  const requestId = useRef(0);
  const startedAt = useRef(0);
  const timers = useRef<number[]>([]);
  const ticker = useRef<number | null>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(true);
  const onEventRef = useRef(onEvent);
  useEffect(() => {
    onEventRef.current = onEvent;
  }, [onEvent]);

  const stopTimers = () => {
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    if (ticker.current !== null) window.clearInterval(ticker.current);
    ticker.current = null;
  };

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      stopTimers();
      controller.current?.abort();
    };
  }, []);

  /** Dispatch only legal events, and report real changes. */
  const send = useCallback((event: LatencyEvent) => {
    const from = phaseRef.current;
    const to = latencyReducer(from, event);
    if (to === from) return false;
    phaseRef.current = to;
    dispatch(event);
    const atMs = event === "START" ? 0 : Math.round(performance.now() - startedAt.current);
    onEventRef.current?.({ atMs, event, from, to });
    return true;
  }, []);

  const start = useCallback(() => {
    if (isBusy(phaseRef.current)) return;
    stopTimers();
    startedAt.current = performance.now();
    if (!send("START")) return;
    const id = ++requestId.current;
    const ctl = new AbortController();
    controller.current = ctl;
    const live = () => mounted.current && id === requestId.current;

    if (skeletonAfterMs !== undefined) {
      timers.current.push(window.setTimeout(() => live() && send("SHOW_SKELETON"), skeletonAfterMs));
    }
    timers.current.push(
      window.setTimeout(() => {
        if (!live()) return;
        send("SLOW");
        const tick = () => setElapsedS(Math.floor((performance.now() - startedAt.current) / 1000));
        tick();
        ticker.current = window.setInterval(tick, 250);
      }, slowAfterMs)
    );

    Promise.resolve()
      .then(() => run(ctl.signal))
      .then(
        (value) => {
          if (!live()) return;
          stopTimers();
          setData({ value });
          send("RESOLVE");
          if (successHoldMs !== undefined) {
            timers.current.push(window.setTimeout(() => live() && send("RESET"), successHoldMs));
          }
        },
        (err: unknown) => {
          if (!live()) return;
          stopTimers();
          setError(err instanceof Error ? err.message : "Request failed");
          send("REJECT");
        }
      );
  }, [run, send, skeletonAfterMs, slowAfterMs, successHoldMs]);

  const cancel = useCallback(() => {
    if (!isBusy(phaseRef.current)) return;
    requestId.current++; // a late result can no longer move the state
    stopTimers();
    controller.current?.abort();
    send("CANCEL");
  }, [send]);

  const reset = useCallback(() => {
    requestId.current++;
    stopTimers();
    send("RESET");
  }, [send]);

  return { phase, busy: isBusy(phase), data, error, elapsedS, start, cancel, reset };
};

"use client";
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

let query: MediaQueryList | null = null;
const getQuery = () => {
  if (!query && typeof window !== "undefined") query = window.matchMedia(QUERY);
  return query;
};

/**
 * A simulated setting, used by X-ray mode so anyone can see what every
 * component does with reduced motion without changing their OS setting.
 * null means "follow the system".
 */
let simulated: boolean | null = null;
const simulationListeners = new Set<() => void>();

/** Override the system setting (true or false), or pass null to follow it again. */
export const simulateReducedMotion = (value: boolean | null) => {
  if (simulated === value) return;
  simulated = value;
  simulationListeners.forEach((notify) => notify());
};

/** Whether the reduced-motion setting is currently simulated rather than read from the system. */
export const reducedMotionSimulated = (): boolean => simulated !== null;

/**
 * Whether the user has asked for reduced motion, read live. Cheap enough to
 * call every frame inside a rAF loop, so the setting takes effect mid-animation.
 */
export const reducedMotionNow = (): boolean => simulated ?? getQuery()?.matches ?? false;

/**
 * Seconds to feed into time-based colour drift (`pastelColour`, `colourField`).
 * With reduced motion the clock stops, so colour still follows the user but no
 * longer drifts on its own.
 */
export const motionTime = (): number => (reducedMotionNow() ? 0 : performance.now() / 1000);

const subscribe = (notify: () => void) => {
  const q = getQuery();
  q?.addEventListener("change", notify);
  simulationListeners.add(notify);
  return () => {
    q?.removeEventListener("change", notify);
    simulationListeners.delete(notify);
  };
};

/** React hook for the same setting. The server snapshot is false, so first paint matches. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, reducedMotionNow, () => false);
